<script lang="ts">
/**
 * Scalar Menu Team Picker component
 *
 * A sub-menu within ScalarMenu that lets users switch between teams
 * or create a new team.
 *
 * @example
 * <ScalarMenuTeamPicker :teams="teams" :team="currentTeam" @update:team="setTeam" />
 */
export default {}
</script>
<script setup lang="ts">
import {
  ScalarIconCaretRight,
  ScalarIconPlus,
  ScalarIconUserSwitch,
} from '@scalar/icons'
import { DropdownMenu } from 'radix-vue/namespaced'
import { computed } from 'vue'

import {
  ScalarDropdownButton,
  ScalarDropdownMenu,
  ScalarListboxCheckbox,
} from '../..'
import { ScalarMenuLink, type ScalarMenuTeamOption } from './'
import ScalarMenuTeamProfile from './ScalarMenuTeamProfile.vue'

const {
  team,
  teams,
  allowAddTeam = true,
} = defineProps<{
  /** The currently selected team */
  team?: ScalarMenuTeamOption | undefined
  /** The list of teams to choose from */
  teams: ScalarMenuTeamOption[]
  /** Whether to disable the "Add team" button */
  allowAddTeam?: boolean
}>()

const emit = defineEmits<{
  /** Emitted when the selected team changes */
  (e: 'update:team', value: ScalarMenuTeamOption | undefined): void
  /** Emitted when the user clicks the "Create new team" button */
  (e: 'add'): void
}>()

/** A model that tracks the team id */
const model = computed<string | undefined>({
  get: () => team?.id,
  set: (v) =>
    emit(
      'update:team',
      teams.find((t) => t.id === v),
    ),
})

defineOptions({ inheritAttrs: false })
</script>
<template>
  <DropdownMenu.Sub>
    <ScalarMenuLink
      :icon="ScalarIconUserSwitch"
      submenu
      v-bind="$attrs">
      <div>Change team</div>
      <ScalarIconCaretRight
        class="ml-auto text-c-2 -mr-px size-3"
        weight="bold" />
    </ScalarMenuLink>
    <DropdownMenu.Portal>
      <DropdownMenu.SubContent
        :as="ScalarDropdownMenu"
        class="max-h-radix-popper z-context-plus"
        :sideOffset="3">
        <DropdownMenu.RadioGroup
          v-model="model"
          class="contents">
          <DropdownMenu.RadioItem
            v-for="t in teams"
            :key="t.id"
            :as="ScalarDropdownButton"
            class="group/item flex items-center"
            :value="t.id">
            <ScalarMenuTeamProfile
              class="-ml-0.75 flex-1 min-w-0"
              :label="t.label"
              :src="t.src" />
            <ScalarListboxCheckbox
              class="ml-auto"
              :selected="t.id === model" />
          </DropdownMenu.RadioItem>
        </DropdownMenu.RadioGroup>
        <DropdownMenu.Item
          v-if="allowAddTeam"
          :as="ScalarDropdownButton"
          class="flex items-center"
          @click="emit('add')">
          <ScalarIconPlus
            class="bg-b-3 -ml-0.75 rounded p-1 size-5 text-c-3"
            weight="bold" />
          Create new team
        </DropdownMenu.Item>
      </DropdownMenu.SubContent>
    </DropdownMenu.Portal>
  </DropdownMenu.Sub>
</template>
